def _date_sort_key(item: dict) -> tuple:
    """발행 날짜(YYYY-MM-DD 또는 YYYY.MM.DD) 내림차순 정렬을 위한 키 생성."""
    raw_date = str(item.get("date", ""))
    nums = re.findall(r"\d+", raw_date)
    d_str = "".join(nums[:3]) if len(nums) >= 3 else "00000000"
    raw_id = str(item.get("id", ""))
    id_num = int(re.sub(r"\D", "", raw_id)) if re.sub(r"\D", "", raw_id) else 0
    return (d_str, id_num)


def _is_new(item: dict) -> bool:
    """실제 발행 시각을 알 수 있을 때만 24시간 이내 새 소식으로 표시해요."""
    # 2026.11.12 jungmin 날짜만 있는 기사는 24시간 이내인지 알 수 없어 배지를 붙이지 않아요.
    published = str(item.get("date", ""))
    if not re.search(r"\d{1,2}:\d{2}", published):
        return False
    try:
        published_at = datetime.fromisoformat(published.replace("Z", "+00:00"))
        kst = timezone(timedelta(hours=9))
        published_at = published_at.replace(tzinfo=kst) if published_at.tzinfo is None else published_at.astimezone(kst)
        age = datetime.now(kst) - published_at
        return timedelta(0) <= age <= timedelta(hours=24)
    except ValueError:
        return False


def _open(nid: str) -> None:
    # 2026.11.12 jungmin 상세를 열기 전의 바다소식 내부 화면을 기억해요.
    S["news_detail_origin"] = "all" if st.query_params.get("view") == "all" and S.get("news_last_view") == "all" else "main"
    S["news_open"] = nid
    news_data.count_view(nid)
    db.clear_cache()


def _close() -> None:
    S.pop("news_open", None)
    S.pop("news_item_applied", None)
    for k in ("item", "n"):
        if k in st.query_params:
            del st.query_params[k]


def _news_home() -> None:
    """서비스 홈이 아닌 바다소식 /news 메인으로 돌아가요."""
    # 2026.11.12 jungmin 내부 화면 상태만 지워 바다소식 메인으로 이동해요.
    S.pop("news_open", None)
    S.pop("news_item_applied", None)
    S["news_detail_origin"] = "main"
    for key in ("view", "page", "item", "n"):
        if key in st.query_params:
            del st.query_params[key]


def _news_previous() -> None:
    """상세에서 직전 내부 목록으로 돌아가고 직접 진입이면 바다소식 홈으로 가요."""
    # 2026.11.12 jungmin 직접 URL 진입으로 유효한 기록이 없으면 바다소식 메인을 사용해요.
    if S.get("news_open") and S.get("news_detail_origin") == "all":
        _close()
    else:
        _news_home()


def _news_navigation() -> None:
    """상세에는 이전 화면과 홈, 전체보기에는 홈만 보여줘요."""
    # 2026.11.12 jungmin 전체보기에서 같은 동작인 이전 화면 버튼을 중복 표시하지 않아요.
    with st.container(horizontal=True, gap="small"):
        if S.get("news_open"):
            st.button("이전 화면", key="news_back_detail",
                      type="secondary", icon=":material/arrow_back:", on_click=_news_previous)
        st.button("바다소식 홈", key=f"news_home_{'detail' if S.get('news_open') else 'all'}",
                  type="secondary", icon=":material/home:", on_click=_news_home)


def _set_page(p: int) -> None:
    S["news_page"] = p


def _set_all_page(p: int) -> None:
    # 2026.11.12 jungmin 전체보기 페이지를 URL에 남겨 재실행·뒤로 가기에도 화면을 유지해요.
    S["news_all_page"] = p
    st.query_params["view"] = "all"
    st.query_params["page"] = str(p)


def _all_page_number(total_pages: int) -> int:
    """전체보기 URL의 페이지 번호를 유효한 범위로 맞춰요."""
    # 2026.11.12 jungmin 잘못된 번호나 기사 수 감소에도 전체보기 경로는 유지해요.
    raw = str(st.query_params.get("page", "1"))
    requested = int(raw) if raw.isdecimal() else 1
    return min(max(1, requested), total_pages)


def _meta(item: dict) -> str:
    return f"{item['source']} · {news_data.date_label(item['date'])} · 조회 {item['views']:,}"


def _clamp(text: str, lines: int = 2) -> str:
    return (f'<p style="display:-webkit-box;-webkit-line-clamp:{lines};-webkit-box-orient:vertical;'
            f'overflow:hidden;margin:.15rem 0 .35rem;line-height:1.6">{html.escape(text)}</p>')


def _category(item: dict) -> str:
    """기사의 제목·요약·출처를 바탕으로 '해양생물' 또는 '해양환경' 분야를 판별한다."""
    text = f"{item.get('title', '')} {item.get('summary', '')} {item.get('source', '')}"
    if any(k in text for k in BIO_KEYWORDS):
        return "해양생물"
    return "해양환경"


