def _news_topic(item: dict) -> str:
    """최신 소식 행에는 제목·요약에 실제로 드러난 해양 주제를 표시해요."""
    # 2026.11.12 jungmin 출처나 기관명만으로 최신 기사 주제를 정하지 않아요.
    title = str(item.get("title", "")).casefold()
    summary = str(item.get("summary", "")).casefold()
    for name in (item.get("source", ""), "해양수산부", "국립수산과학원", "국립해양생물자원관", "정책브리핑"):
        if name:
            title = title.replace(str(name).casefold(), "")
            summary = summary.replace(str(name).casefold(), "")
    return next((label for label, _, words in RECOMMEND_TOPICS
                 if any(word.casefold() in title or word.casefold() in summary for word in words)), "바다 소식")


def _tag(item: dict) -> str:
    # 1. AI 요약된 글이면 무조건 파란색 [AI 요약] 칩 노출!
    if item.get("ai"):
        return ui.chip("AI 요약", "sea")
    # 2. 수동 등록/요약 글
    if item.get("id", "").startswith("n_ko_") or "수동" in item.get("source", ""):
        return ui.chip("수동 요약")
    # 3. 저작권 보호를 위한 원문 발췌 글
    return ui.chip("원문 발췌")


def _cat_chip(item: dict) -> str:
    cat = _category(item)
    return ui.chip(cat, "sea" if cat == "해양생물" else "sand")


def _is_example(item: dict) -> bool:
    """초기 시연용 기사를 실제로 수집한 소식과 구분한다."""
    return item.get("url", "").startswith(("https://example.com/", "http://example.com/")) or item.get("source", "").startswith("예시 ")


